using System.Text;
using Domain.Assessment;
using Domain.Vocabulary;

namespace Infrastructure.Vocabulary;

/// <summary>
/// The curated topic catalog - the single learning spine shared by every skill (PROJECT-SPEC
/// module 4): 50 distinct, level-appropriate topics for each CEFR level (A1–C2), 300 in total.
/// Each entry carries only its metadata - an English title, a vetted Uzbek label (rule 11), a
/// theme category and a grammar focus code; each skill's teaching content (passage, reading,
/// grammar lesson, listening transcript, writing prompt) is generated by the LLM on first open and
/// cached (rules 8, 10). Topics progress from concrete daily life (A1) to abstract, academic
/// themes (C2). 10 thematic categories × 5 topics = 50 per level.
/// </summary>
public static class VocabularyTopicCatalog
{
    private static readonly DateTimeOffset SeededAt = new(2026, 1, 1, 0, 0, 0, TimeSpan.Zero);

    /// <summary>How many topics each thematic category contributes (10 categories × 5 = 50/level).</summary>
    public const int TopicsPerCategory = 5;

    /// <summary>
    /// Topics per CEFR level. Every skill (vocabulary, grammar, reading, listening, writing,
    /// speaking) teaches this same set of 50 topics per level - the shared learning spine.
    /// </summary>
    public const int TopicsPerLevel = 50;

    /// <summary>All 300 curated topics (50 per CEFR level), the spine shared by every skill.</summary>
    public static IReadOnlyList<VocabularyTopic> Topics()
    {
        var topics = new List<VocabularyTopic>(TopicsPerLevel * 6);
        AddLevel(topics, CefrLevel.A1, A1, A1Grammar);
        AddLevel(topics, CefrLevel.A2, A2, A2Grammar);
        AddLevel(topics, CefrLevel.B1, B1, B1Grammar);
        AddLevel(topics, CefrLevel.B2, B2, B2Grammar);
        AddLevel(topics, CefrLevel.C1, C1, C1Grammar);
        AddLevel(topics, CefrLevel.C2, C2, C2Grammar);
        return topics;
    }

    // Emits the first TopicsPerCategory topics of each category (the most fundamental ones), and
    // assigns each a grammar focus by cycling through the level's syllabus. With 50 topics and a
    // 10-code syllabus, every grammar point is taught in five different topic contexts - so the
    // 50 topics deterministically cover the level's whole CEFR grammar progression.
    //
    // The learning Sequence is simply the catalog declaration order: all five topics of the first
    // category, then all five of the next, and so on (a stable 0..49 progression). Every skill
    // reads the shared spine in this order, so the level roadmap (/levels) lists topics in the very
    // same category-by-category order in which the skill catalogs (vocabulary, speaking, …) group
    // them - one coherent, course-like order across all six modules.
    private static void AddLevel(
        List<VocabularyTopic> topics, CefrLevel level,
        (string Category, T[] Items)[] groups, string[] grammarSyllabus)
    {
        var focusCount = grammarSyllabus.Length;
        var index = 0;
        foreach (var (category, items) in groups)
            foreach (var item in items.Take(TopicsPerCategory))
            {
                // Grammar focus still cycles through the syllabus so every point recurs across five
                // topics - but it no longer drives the display order, only which lesson a topic uses.
                var focus = grammarSyllabus[index % focusCount];
                // Sequence follows declaration order so the spine reads category by category.
                var sequence = index;
                topics.Add(VocabularyTopic.Curate(
                    Slug(level, item.En), item.En, item.Uz, category, focus, level, SeededAt, sequence));
                index++;
            }
    }

    // ─── Per-level grammar syllabi (kebab-case focus codes). Cycled across each level's 50 topics
    //     so coverage is deterministic. The Grammar module resolves these codes to its 5-step
    //     lessons and vetted Uzbek explanation templates (rule 11). 10 codes/level → 5 contexts each.
