    /// <summary>A stable per-level slug (e.g. "a1-my-family"), unique across the whole catalog.</summary>
    private static string Slug(CefrLevel level, string title)
    {
        var sb = new StringBuilder(level.ToString().ToLowerInvariant());
        sb.Append('-');
        var lastDash = true;
        foreach (var c in title.ToLowerInvariant())
        {
            if (char.IsLetterOrDigit(c))
            {
                sb.Append(c);
                lastDash = false;
            }
            else if (!lastDash)
            {
                sb.Append('-');
                lastDash = true;
            }
        }

        return sb.ToString().TrimEnd('-');
    }

